# Unicode character names for the namereplace error handler.
# Algorithmic names are computed without storing their ranges.
def name(number):
    if 0xac00 <= number <= 0xd7a3:
        lead = ('G', 'GG', 'N', 'D', 'DD', 'R', 'M', 'B', 'BB', 'S', 'SS', '', 'J', 'JJ', 'C', 'K', 'T', 'P', 'H')
        vowel = ('A', 'AE', 'YA', 'YAE', 'EO', 'E', 'YEO', 'YE', 'O', 'WA', 'WAE', 'OE', 'YO', 'U', 'WEO', 'WE', 'WI', 'YU', 'EU', 'YI', 'I')
        tail = ('', 'G', 'GG', 'GS', 'N', 'NJ', 'NH', 'D', 'L', 'LG', 'LM', 'LB', 'LS', 'LT', 'LP', 'LH', 'M', 'B', 'BS', 'S', 'SS', 'NG', 'J', 'C', 'K', 'T', 'P', 'H')
        n = number - 0xac00
        return 'HANGUL SYLLABLE ' + lead[n // 588] + vowel[(n // 28) % 21] + tail[n % 28]
    if 13312 <= number <= 19903 or 19968 <= number <= 40959 or 131072 <= number <= 173791 or 173824 <= number <= 177977 or 177984 <= number <= 178205 or 178208 <= number <= 183969 or 183984 <= number <= 191456 or 196608 <= number <= 201546 or 201552 <= number <= 205743:
        return 'CJK UNIFIED IDEOGRAPH-' + ("%X" % number)
    if 63744 <= number <= 64109 or 64112 <= number <= 64217 or 194560 <= number <= 195101:
        return 'CJK COMPATIBILITY IDEOGRAPH-' + ("%X" % number)
    block = _names.get(number >> 8, '')
    marker = '\n%02x:' % (number & 255)
    pos = block.find(marker)
    if pos < 0:
        return None
    pos += len(marker)
    return block[pos:block.find('\n', pos)]


def lookup(spelling):
    spelling = spelling.upper()
    marker = ':' + spelling + '\n'
    for page, block in _names.items():
        pos = block.find(marker)
        if pos >= 0:
            return chr((page << 8) + int(block[pos - 2:pos], 16))
    for prefix in ('CJK UNIFIED IDEOGRAPH-', 'CJK COMPATIBILITY IDEOGRAPH-'):
        if spelling.startswith(prefix):
            try:
                number = int(spelling[len(prefix):], 16)
            except ValueError:
                break
            if name(number) == spelling:
                return chr(number)
    if spelling.startswith('HANGUL SYLLABLE '):
        for number in range(0xac00, 0xd7a4):
            if name(number) == spelling:
                return chr(number)
    raise KeyError('undefined character name ' + spelling)

